using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace Cirrus.SourceGenerators;

[Generator]
public class SqlResourceGenerator : IIncrementalGenerator
{
    private const string SqlResourceAttributeSource = """
// <auto-generated/>

using System;

namespace Cirrus.Generated.Attributes;

[AttributeUsage(AttributeTargets.Class, Inherited = false)]
internal class SqlResourceAttribute(string root = "SQL") : Attribute
{
    public string Root { get; } = root;
}
""";

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(ctx =>
        {
            ctx.AddSource("SqlResourceAttribute.g.cs", SourceText.From(SqlResourceAttributeSource, Encoding.UTF8));
        });
        
        IncrementalValuesProvider<TargetClassInfo> targetClasses = context.SyntaxProvider
            .ForAttributeWithMetadataName(
                fullyQualifiedMetadataName: "Cirrus.Generated.Attributes.SqlResourceAttribute",
                predicate: static (node, _) => node is ClassDeclarationSyntax classDecl
                    && classDecl.Modifiers.Any(SyntaxKind.PartialKeyword),
                transform: static (ctx, _) => GetTargetClassInfo(ctx))
            .Where(static info => info is not null)!;

        var sqlFiles = context.AdditionalTextsProvider
            .Where(static file => file.Path.EndsWith(".sql", StringComparison.OrdinalIgnoreCase))
            .Select(static (file, ct) => new SqlFileInfo(
                fullPath: NormalizePath(file.Path),
                content: file.GetText(ct)?.ToString() ?? string.Empty));

        var projectDirProvider = context.AnalyzerConfigOptionsProvider
            .Select(static (provider, _) =>
            {
                provider.GlobalOptions.TryGetValue("build_property.projectdir", out var projectDir);
                return string.IsNullOrWhiteSpace(projectDir) ? null : NormalizePath(projectDir!);
            });

        var combined = targetClasses
            .Combine(projectDirProvider)
            .Combine(sqlFiles.Collect());

        context.RegisterSourceOutput(combined, static (spc, source) =>
        {
            var (classAndProjectDir, allSqlFiles) = source;
            var (targetClass, msbuildProjectDir) = classAndProjectDir;

            var baseDir = msbuildProjectDir ?? targetClass.SourceFileDirectory;
            var rootSqlDir = NormalizePath(Path.Combine(baseDir, targetClass.RootFolder)).TrimEnd('/') + "/";

            FolderNode rootNode = new(targetClass.ClassName);

            foreach (var sqlFile in allSqlFiles)
            {
                if (!sqlFile.FullPath.StartsWith(rootSqlDir, StringComparison.OrdinalIgnoreCase))
                    continue;

                var relativePath = sqlFile.FullPath.Substring(rootSqlDir.Length);
                var segments = relativePath.Split(['/'], StringSplitOptions.RemoveEmptyEntries);

                if (segments.Length == 0)
                    continue;

                var current = rootNode;
                for (var i = 0; i < segments.Length - 1; i++)
                {
                    var folderName = SanitizeIdentifier(segments[i]);
                    current = current.GetOrAddFolder(folderName);
                }

                var fileNameWithoutExt = Path.GetFileNameWithoutExtension(segments[segments.Length - 1]);
                var memberName = SanitizeIdentifier(fileNameWithoutExt);
                current.Files[memberName] = sqlFile.Content;
            }

            var generatedCode = EmitSource(targetClass, rootNode);
            spc.AddSource($"{targetClass.ClassName}.g.cs", SourceText.From(generatedCode, Encoding.UTF8));
        });
    }

    private static TargetClassInfo? GetTargetClassInfo(GeneratorAttributeSyntaxContext ctx)
    {
        if (ctx.TargetSymbol is not INamedTypeSymbol classSymbol)
            return null;

        var attribute = ctx.Attributes[0];
        var rootFolder = "SQL";

        if (attribute.ConstructorArguments.Length > 0 &&
            attribute.ConstructorArguments[0].Value is string argValue &&
            !string.IsNullOrWhiteSpace(argValue))
        {
            rootFolder = argValue;
        }

        var ns = classSymbol.ContainingNamespace.IsGlobalNamespace
            ? null
            : classSymbol.ContainingNamespace.ToDisplayString();

        var accessibility = SyntaxFacts.GetText(classSymbol.DeclaredAccessibility);
        var sourceFileDir = NormalizePath(Path.GetDirectoryName(ctx.TargetNode.SyntaxTree.FilePath) ?? string.Empty);

        return new TargetClassInfo(
            @namespace: ns,
            className: classSymbol.Name,
            accessibility: accessibility,
            rootFolder: rootFolder,
            sourceFileDirectory: sourceFileDir);
    }

    private static string EmitSource(TargetClassInfo target, FolderNode rootNode)
    {
        StringBuilder sb = new();
        sb.AppendLine("// <auto-generated/>");
        sb.AppendLine();

        if (!string.IsNullOrEmpty(target.Namespace))
        {
            sb.AppendLine($"namespace {target.Namespace};");
            sb.AppendLine();
        }

        EmitFolderNode(sb, rootNode, 0, isRoot: true, target.Accessibility);

        return sb.ToString();
    }

    private static void EmitFolderNode(StringBuilder sb, FolderNode node, int indent, bool isRoot, string accessibility)
    {
        string pad = new(' ', indent * 4);
        var modifier = isRoot ? $"{accessibility} static partial class" : "public static class";

        sb.AppendLine($"{pad}{modifier} {node.Name}");
        sb.AppendLine($"{pad}{{");

        string innerPad = new(' ', (indent + 1) * 4);
        
        foreach (var file in node.Files.OrderBy(k => k.Key, StringComparer.Ordinal))
        {
            var escapedSql = SymbolDisplay.FormatLiteral($"\n{file.Value}\n", quote: true);
            sb.AppendLine($"{innerPad}public const string {file.Key} = {escapedSql};");
        }
        
        var contentBefore = node.Files.Any();
        
        foreach (var subFolder in node.SubFolders.Values.OrderBy(f => f.Name, StringComparer.Ordinal))
        {
            if (contentBefore) sb.AppendLine();
            EmitFolderNode(sb, subFolder, indent + 1, isRoot: false, accessibility: "public");
            contentBefore = true;
        }

        sb.AppendLine($"{pad}}}");
    }

    private static string NormalizePath(string path) => path.Replace('\\', '/');

    private static string SanitizeIdentifier(string raw)
    {
        if (string.IsNullOrEmpty(raw))
            return "_";

        StringBuilder sb = new(raw.Length);
        if (!SyntaxFacts.IsIdentifierStartCharacter(raw[0]))
            sb.Append('_');

        foreach (var c in raw)
        {
            sb.Append(SyntaxFacts.IsIdentifierPartCharacter(c) ? c : '_');
        }

        var candidate = sb.ToString();
        return SyntaxFacts.GetKeywordKind(candidate) != SyntaxKind.None ? $"@{candidate}" : candidate;
    }

    private sealed class TargetClassInfo(string? @namespace, string className, string accessibility, string rootFolder, string sourceFileDirectory)
    {
        public string? Namespace { get; } = @namespace;
        public string ClassName { get; } = className;
        public string Accessibility { get; } = accessibility;
        public string RootFolder { get; } = rootFolder;
        public string SourceFileDirectory { get; } = sourceFileDirectory;
    }

    private sealed class SqlFileInfo(string fullPath, string content)
    {
        public string FullPath { get; } = fullPath;
        public string Content { get; } = content;
    }

    private sealed class FolderNode(string name)
    {
        public string Name { get; } = name;
        public Dictionary<string, FolderNode> SubFolders { get; } = new(StringComparer.Ordinal);
        public Dictionary<string, string> Files { get; } = new(StringComparer.Ordinal);

        public FolderNode GetOrAddFolder(string name)
        {
            if (SubFolders.TryGetValue(name, out var folder)) return folder;
            folder = new FolderNode(name);
            SubFolders[name] = folder;
            return folder;
        }
    }
}